class Solution:
    def lowestCommonAncestor(self, root, p, q):
        # iterative to stay safe on deep trees: record parents, then walk up
        parent = {root: None}
        stack = [root]
        while p not in parent or q not in parent:
            node = stack.pop()
            for c in (node.left, node.right):
                if c:
                    parent[c] = node
                    stack.append(c)
        ancestors = set()
        while p:
            ancestors.add(p)
            p = parent[p]
        while q not in ancestors:
            q = parent[q]
        return q

