class NumArray:
    def __init__(self, nums):
        self.n = len(nums)
        self.a = list(nums)
        self.t = [0] * (self.n + 1)
        for i, x in enumerate(nums):          # O(n) build
            j = i + 1
            self.t[j] += x
            k = j + (j & -j)
            if k <= self.n:
                self.t[k] += self.t[j]

    def _prefix(self, i):                      # sum of first i values
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s

    def update(self, index, val):
        d = val - self.a[index]
        self.a[index] = val
        i = index + 1
        while i <= self.n:
            self.t[i] += d
            i += i & -i

    def sumRange(self, left, right):
        return self._prefix(right + 1) - self._prefix(left)

