    def __init__(self, nestedList):
        self.stack = [[nestedList, 0]]          # (list, next position)

    def _advance(self):
        while self.stack:
            lst, i = self.stack[-1]
            if i == len(lst):
                self.stack.pop()
            elif lst[i].isInteger():
                return True
            else:
                self.stack[-1][1] += 1
                self.stack.append([lst[i].getList(), 0])
        return False

    def next(self):
        self._advance()
        lst, i = self.stack[-1]
        self.stack[-1][1] += 1
        return lst[i].getInteger()

    def hasNext(self):
        return self._advance()

