class Solution:
    def treeToDoublyList(self, root):
        if not root:
            return None
        first = prev = None
        stack, node = [], root
        while stack or node:                  # iterative inorder
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            if prev:
                prev.right, node.left = node, prev
            else:
                first = node
            prev = node
            node = node.right
        prev.right, first.left = first, prev  # close the circle
        return first

