class Solution:
    def intervalIntersection(self, A, B):
        i = j = 0
        out = []
        while i < len(A) and j < len(B):
            lo, hi = max(A[i][0], B[j][0]), min(A[i][1], B[j][1])
            if lo <= hi:
                out.append([lo, hi])
            if A[i][1] < B[j][1]:          # the interval that ends first can't overlap anything else
                i += 1
            else:
                j += 1
        return out

