class Solution:
    def carPooling(self, trips, capacity):
        events = []
        for n, a, b in trips:
            events.append((a, n))
            events.append((b, -n))
        load = 0
        for _, d in sorted(events):        # drop-offs sort before pick-ups at the same km
            load += d
            if load > capacity:
                return False
        return True

